/**
 * The narrator. Each line is looked up in this order:
 *   1. a custom recording made in the parent dashboard (IndexedDB)
 *   2. public/audio/<voice>/<lang>/<name>.mp3   (generated by scripts/generate_audio.py)
 *   3. the same clip from the default persona (sarah)
 *   4. only if nothing exists: the device's speech synthesis
 * Lines are queued so they never talk over each other.
 */
import { Howl } from 'howler';
import { VOICES, byId, type Lang, type VoiceId } from '@/data/content';
import { S } from '@/store/settings';
import { audio } from './AudioEngine';
import { clipStore } from './clipStore';

interface Item { text: string; lang: Lang; clip?: string }
interface Src { url: string; key: string; format: string; custom: boolean }
const BASE = import.meta.env.BASE_URL + 'audio/';

class SpeechEngine {
  ok = typeof window !== 'undefined' && 'speechSynthesis' in window && 'SpeechSynthesisUtterance' in window;
  lists: Record<Lang, SpeechSynthesisVoice[]> = { ar: [], en: [] };
  loaded = false;
  /** Which generated files exist, per persona. */
  manifest: Record<string, Set<string>> = {};
  clipsOn = false;
  ready: Promise<void>;
  private miss = new Set<string>();
  private ver = new Map<string, number>();
  private q: Item[] = [];
  private busy = false;
  private tok = 0;
  private howl: Howl | null = null;
  private keep: SpeechSynthesisUtterance | null = null;
  private listeners = new Set<() => void>();

  constructor() {
    this.ready = this.loadManifest();
    void clipStore.keys();
    if (this.ok) {
      this.loadVoices();
      try { speechSynthesis.addEventListener('voiceschanged', () => this.loadVoices()); } catch { /* older browsers */ }
    }
  }
  subscribe(f: () => void) { this.listeners.add(f); return () => { this.listeners.delete(f); }; }
  private emit() { this.listeners.forEach(f => f()); }

  async loadManifest() {
    try {
      const r = await fetch(BASE + 'manifest.json', { cache: 'no-cache' });
      if (!r.ok) throw new Error(String(r.status));
      const m = (await r.json()) as { voices?: Record<string, string[]> };
      this.manifest = {};
      Object.entries(m.voices || {}).forEach(([v, list]) => { this.manifest[v] = new Set(list); });
      this.clipsOn = Object.values(this.manifest).some(s => s.size > 0);
    } catch { this.manifest = {}; this.clipsOn = false; }
    this.emit();
  }
  private loadVoices() {
    let v: SpeechSynthesisVoice[] = [];
    try { v = speechSynthesis.getVoices() || []; } catch { /* unavailable */ }
    const of = (re: RegExp, first: string, second: string) => {
      const rank = (x: SpeechSynthesisVoice) => { const l = x.lang.replace('_', '-').toLowerCase(); return l === first ? 0 : l === second ? 1 : 2; };
      return v.filter(x => re.test(x.lang)).sort((a, b) => rank(a) - rank(b));
    };
    this.lists = { ar: of(/^ar/i, 'ar-sa', 'ar-eg'), en: of(/^en/i, 'en-us', 'en-gb') };
    this.loaded = v.length > 0; this.emit();
  }
  /** True when a line in this language can be neither played nor synthesised: the target then stays on screen. */
  missing(lang: Lang) { return !this.clipsOn && (!this.ok || (this.loaded && !this.lists[lang].length)); }
  hasFile(voice: VoiceId, clip: string) { return !!this.manifest[voice]?.has(clip); }
  /** Call after a file was regenerated on disk so the browser fetches the new one. */
  bump(voice: VoiceId, clip: string) {
    const k = voice + '/' + clip; this.ver.set(k, (this.ver.get(k) || 0) + 1); this.miss.delete(k);
    (this.manifest[voice] ||= new Set()).add(clip); this.clipsOn = true; this.emit();
  }

  private voiceFor(id: VoiceId, lang: Lang) {
    const L = this.lists[lang] || [];
    const FEM = /(female|laila|leila|mariam|hoda|salma|zariyah|amira|hala|fatima|sana|amina|zeina|samantha|zira|susan|karen|victoria|moira|tessa|jenny|aria|hazel|google us english)/i;
    const MAL = /(male|majed|maged|tarik|naayf|hamed|ahmed|omar|shakir|bassel|fahed|david|mark|daniel|alex|fred|george|james|guy|ryan)/i;
    const fem = L.find(v => FEM.test(v.name));
    const mal = L.find(v => MAL.test(v.name) && !FEM.test(v.name));
    if (id === 'ahmed') return mal || L.find(v => v !== fem) || L[0];
    return fem || L.find(v => v !== mal) || L[0];
  }

  /** Where a clip should be played from for a persona; null when only speech synthesis is left. */
  async src(clip: string, voice: VoiceId = S().voice, strict = false): Promise<Src | null> {
    await this.ready;
    const ck = voice + '/' + clip, custom = await clipStore.get(ck);
    if (custom) return { url: custom.url, key: ck, format: custom.format, custom: true };
    for (const v of strict ? [voice] : [voice, 'sarah' as VoiceId]) {
      const k = v + '/' + clip;
      if (this.manifest[v]?.has(clip) && !this.miss.has(k)) {
        const n = this.ver.get(k);
        return { url: BASE + k + '.mp3' + (n ? '?v=' + n : ''), key: k, format: 'mp3', custom: false };
      }
    }
    return null;
  }

  say(text: string, flush?: boolean, lang: Lang = 'ar', clip?: string) {
    if (S().muted) return;
    if (flush) this.stop();
    this.q.push({ text, lang: lang === 'en' ? 'en' : 'ar', clip });
    if (!this.busy) void this.next();
  }
  private async next(): Promise<void> {
    const it = this.q.shift();
    if (!it) { this.busy = false; audio.duck(false); return; }
    this.busy = true; audio.duck(true);
    const tok = ++this.tok, done = () => { if (tok === this.tok) void this.next(); };
    let src: Src | null = null;
    if (it.clip) { try { src = await this.src(it.clip); } catch { /* fall through to TTS */ } if (tok !== this.tok) return; }
    if (!src) return this.tts(it, done);
    this.playUrl(src, ok => { if (ok) done(); else if (tok === this.tok) this.tts(it, done); });
  }
  private playUrl(src: Src, end: (ok: boolean) => void) {
    let fin = false;
    const finish = (ok: boolean, miss?: boolean) => {
      if (fin) return; fin = true;
      if (miss && !src.custom) this.miss.add(src.key);
      try { h.unload(); } catch { /* already gone */ }
      if (this.howl === h) this.howl = null;
      end(ok);
    };
    const h = new Howl({
      src: [src.url], format: [src.format], html5: false, volume: 1,
      onend: () => finish(true), onloaderror: () => finish(false, true), onplayerror: () => finish(false, false),
    });
    this.howl = h; h.play();
  }
  private tts(it: Item, done: () => void) {
    if (!this.ok) return done();
    try {
      const u = new SpeechSynthesisUtterance(it.text), p = byId(VOICES, S().voice), v = this.voiceFor(S().voice, it.lang);
      if (v) { u.voice = v; u.lang = v.lang.replace('_', '-'); } else u.lang = it.lang === 'en' ? 'en-US' : 'ar-SA';
      u.pitch = p.pitch; u.rate = p.rate * (it.lang === 'en' ? .92 : 1); u.volume = 1; this.keep = u;
      let f = false;
      const fin = () => { if (!f) { f = true; clearTimeout(t); done(); } }, t = setTimeout(fin, 1500 + it.text.length * 230);
      u.onend = u.onerror = fin;
      speechSynthesis.speak(u);
    } catch { done(); }
  }
  stop() {
    this.tok++; this.q = []; this.busy = false; audio.duck(false);
    if (this.howl) { try { this.howl.unload(); } catch { /* already gone */ } this.howl = null; }
    try { if (this.ok) speechSynthesis.cancel(); } catch { /* unavailable */ }
  }

  /** Dashboard: play one persona's version of a clip. Resolves false when that persona has no file for it. */
  async preview(voice: VoiceId, clip: string): Promise<boolean> {
    this.stop();
    const src = await this.src(clip, voice, true);
    if (!src) return false;
    return new Promise(res => this.playUrl(src, res));
  }
  /** Dashboard: play an arbitrary blob (a fresh recording before it is saved). */
  playBlob(url: string, format: string) { this.stop(); this.playUrl({ url, key: 'preview', format, custom: true }, () => {}); }
}

export const Speech = new SpeechEngine();
